{
  "name": "Agilent VSpin 微孔板离心机",
  "name_en": "Agilent VSpin Microplate Centrifuge",
  "manufacturer": "Agilent",
  "description": "一款用于实验室自动化系统的微孔板离心机，可对样品板进行装载、卸载、开关门、锁定转篮并执行离心运行。常用于微孔板样品的短时离心、收集液滴和自动化流程中的板级前处理。",
  "description_en": "An automated microplate centrifuge for laboratory workflows. It can load and unload plates, open and close the door, lock the bucket, and perform spin operations. It is commonly used for short spins, collecting droplets, and plate-level sample preparation in automated lab systems.",
  "tag_hints": [
    "microplate centrifugation",
    "lab automation",
    "robotic plate loading",
    "bucket lock",
    "door interlock",
    "RPM and tachometer",
    "g-force conversion"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭装载位或访问机构。",
      "description_en": "Close the loading position or access mechanism."
    },
    {
      "action_name": "auto-load",
      "description": "将微孔板装入离心机。",
      "description_en": "Load a microplate into the centrifuge."
    },
    {
      "action_name": "auto-open",
      "description": "打开装载位或访问机构。",
      "description_en": "Open the loading position or access mechanism."
    },
    {
      "action_name": "auto-park",
      "description": "将机构移至停靠位。",
      "description_en": "Move the mechanism to its park position."
    },
    {
      "action_name": "auto-send_command",
      "description": "向设备发送原始控制命令。",
      "description_en": "Send a raw control command to the device."
    },
    {
      "action_name": "auto-serialize",
      "description": "序列化当前设备配置或状态。",
      "description_en": "Serialize the current device configuration or state."
    },
    {
      "action_name": "auto-setup",
      "description": "设置并准备设备进入工作状态。",
      "description_en": "Set up and prepare the device for operation."
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前运行或运动。",
      "description_en": "Stop the current operation or motion."
    },
    {
      "action_name": "auto-unload",
      "description": "将微孔板从离心机中取出。",
      "description_en": "Unload a microplate from the centrifuge."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备状态。",
      "description_en": "Get device status."
    },
    {
      "action_name": "auto-bucket_1_remainder",
      "description": "获取 1 号转篮的余量值。",
      "description_en": "Get the remainder value for bucket 1."
    },
    {
      "action_name": "auto-set_bucket_1_position_to_current",
      "description": "将当前位置信息定义为 1 号转篮位置。",
      "description_en": "Define the current position as the bucket 1 position."
    },
    {
      "action_name": "auto-get_bucket_1_position",
      "description": "获取 1 号转篮位置。",
      "description_en": "Get the bucket 1 position."
    },
    {
      "action_name": "auto-get_position",
      "description": "获取当前位置。",
      "description_en": "Get the current position."
    },
    {
      "action_name": "auto-get_tachometer",
      "description": "获取转速计读数。",
      "description_en": "Get the tachometer reading."
    },
    {
      "action_name": "auto-get_home_position",
      "description": "获取原点位置。",
      "description_en": "Get the home position."
    },
    {
      "action_name": "auto-get_bucket_locked",
      "description": "获取转篮是否锁定。",
      "description_en": "Get whether the bucket is locked."
    },
    {
      "action_name": "auto-get_door_open",
      "description": "获取门是否打开。",
      "description_en": "Get whether the door is open."
    },
    {
      "action_name": "auto-get_door_locked",
      "description": "获取门是否锁定。",
      "description_en": "Get whether the door is locked."
    },
    {
      "action_name": "auto-configure_and_initialize",
      "description": "配置并初始化设备。",
      "description_en": "Configure and initialize the device."
    },
    {
      "action_name": "auto-set_configuration_data",
      "description": "设置配置数据。",
      "description_en": "Set configuration data."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化设备。",
      "description_en": "Initialize the device."
    },
    {
      "action_name": "auto-open_door",
      "description": "打开离心机门。",
      "description_en": "Open the centrifuge door."
    },
    {
      "action_name": "auto-close_door",
      "description": "关闭离心机门。",
      "description_en": "Close the centrifuge door."
    },
    {
      "action_name": "auto-lock_door",
      "description": "锁定离心机门。",
      "description_en": "Lock the centrifuge door."
    },
    {
      "action_name": "auto-unlock_door",
      "description": "解锁离心机门。",
      "description_en": "Unlock the centrifuge door."
    },
    {
      "action_name": "auto-lock_bucket",
      "description": "锁定转篮。",
      "description_en": "Lock the bucket."
    },
    {
      "action_name": "auto-unlock_bucket",
      "description": "解锁转篮。",
      "description_en": "Unlock the bucket."
    },
    {
      "action_name": "auto-go_to_bucket1",
      "description": "移动到 1 号转篮位置。",
      "description_en": "Move to the bucket 1 position."
    },
    {
      "action_name": "auto-go_to_bucket2",
      "description": "移动到 2 号转篮位置。",
      "description_en": "Move to the bucket 2 position."
    },
    {
      "action_name": "auto-go_to_position",
      "description": "移动到指定位置。",
      "description_en": "Move to a specified position."
    },
    {
      "action_name": "auto-g_to_rpm",
      "description": "将离心力数值换算为转速。",
      "description_en": "Convert a centrifugal force value to RPM."
    },
    {
      "action_name": "auto-spin",
      "description": "执行离心运行。",
      "description_en": "Run a centrifugation cycle."
    }
  ]
}

